// Execute Command hands us { exitCode, stdout, stderr }. The scraper prints
// exactly one JSON document on stdout - a snapshot, a skipped tick, or
// {"ok": false, ...} - so anything unparseable here is a container problem
// (no node, a half-finished checkout), not a scraping problem.
const out = [];

for (const item of $input.all()) {
  const stdout = String(item.json.stdout ?? '').trim();
  const stderr = String(item.json.stderr ?? '').trim();
  const exitCode = item.json.exitCode ?? 0;

  if (!stdout) {
    out.push({ json: { ok: false, error: `scraper printed nothing (exit ${exitCode})`, stderr: stderr.slice(-2000) } });
    continue;
  }

  // Ignore anything npm or the shell may have printed before the document.
  const start = stdout.indexOf('{');
  try {
    const doc = JSON.parse(start > 0 ? stdout.slice(start) : stdout);
    doc.exitCode = exitCode;
    if (stderr) doc.log = stderr.slice(-2000);
    out.push({ json: doc });
  } catch (err) {
    out.push({
      json: {
        ok: false,
        error: `unparseable scraper output: ${err.message}`,
        stdout: stdout.slice(0, 2000),
        stderr: stderr.slice(-2000),
      },
    });
  }
}

return out;

// One item per stock. `doc.results` is already one entry per company, each
// carrying its formatted MCP data under `data`, so this is a plain fan-out —
// there is no scraped row left to match a dump back to.
//
// Everything under `data` came from the screener MCP server. Moneycontrol is
// only the scan (which stocks, and what their symbol is); none of its own
// numbers are in here.
//
// No dedup: this is the full current scan every run, so decide downstream what
// counts as new.
const out = [];

for (const item of $input.all()) {
  const doc = item.json;
  const base = {
    ok: true,
    runId: doc.runId ?? null,
    source: doc.source ?? null,
    scrapedAt: doc.scrapedAt ?? null,
    cacheEnabled: doc.cacheEnabled ?? false,
    truncated: doc.truncated ?? false,
  };

  for (const stock of doc.results ?? []) {
    out.push({
      json: {
        ...base,
        company: stock.company ?? null,
        // An NSE ticker (DHOOTTRANS) or, for a BSE-only scrip, its code (541735).
        symbol: stock.symbol ?? null,
        exchange: stock.exchange ?? null,
        scId: stock.scId ?? null,
        events: stock.events ?? [],
        // ok | failed | pending | unresolved. pending = the run deadline arrived
        // before this stock was dumped and the next tick picks it up, not a failure.
        status: stock.status ?? null,
        error: stock.error ?? null,
        counts: stock.data?.counts ?? null,
        issues: stock.data?.issues ?? [],
        data: stock.data ?? null,
      },
    });
  }
}

return out.length > 0
  ? out
  : [{ json: { ok: true, skipped: true, reason: 'no companies listed on the page right now' } }];
